// ON CONFLICT DO NOTHING на дублі file_id віддає 0 рядків, але alwaysOutputData
// у 'Зберегти фото' все одно шле далі порожній item — інакше вся гілка обривається
// ще на INSERT і 'Підтвердити фото' взагалі не спрацьовує. Тут явно перевіряємо:
// id є — це новий запис, ведемо його на завантаження й Nextcloud; id немає — дубль,
// нічого не тягнемо і нічого не пишемо, це правильна поведінка.
const it = $input.first();
if (!it || it.json.id == null) return [];
return [it];

// Гілка для чеків: далі йде лише те, що водій підписав/розпізнав як чек.
// Все інше (фото обʼєкта, одометра) сюди не заходить — receipt-bot на LXC 414
// сам розпізнає вміст через ROG vision, дублювати цю класифікацію не треба.
const kind = $('Розбір оновлення').item.json.photo_kind;
if (kind !== 'receipt') return [];
return $input.all();
